"use strict"
function bamei_sort(str) {
const table = {
'ァ': 'ア', 'ィ': 'イ', 'ゥ': 'ウ', 'ヴ': 'ウ', 'ェ': 'エ', 'ォ': 'オ',
'ガ': 'カ', 'ギ': 'キ', 'グ': 'ク', 'ゲ': 'ケ', 'ゴ': 'コ',
'ザ': 'サ', 'ジ': 'シ', 'ズ': 'ス', 'ゼ': 'セ', 'ゾ': 'ソ',
'ダ': 'タ', 'ヂ': 'チ', 'ヅ': 'ツ', 'ッ': 'ツ', 'デ': 'テ', 'ド': 'ト',
'バ': 'ハ', 'ビ': 'ヒ', 'ブ': 'フ', 'ベ': 'ヘ', 'ボ': 'ホ',
'パ': 'ハ', 'ピ': 'ヒ', 'プ': 'フ', 'ペ': 'ヘ', 'ポ': 'ホ',
'ャ': 'ヤ', 'ュ': 'ユ', 'ョ': 'ヨ',
'ヮ': 'ワ', 'ー': 'ヵ',
};
let result = '';
for (let i = 0; i < str.length; i++){
const char = str[i];
if (table[char]){
result += table[char];
} else {
result += char;
}
}
return result;
}
