$measureWrap.children('ul').append($measureTarget);
$('body').append($measureWrap);
}
$measureTarget.children('span').slice(0, 3).each(function () {
marginLeft += $(this).outerWidth() || 0;
});
marginLeft += parseFloat($measureTarget.children('span').eq(1).css('margin-left')) || 0;
