$(function(){
const syncedCheckboxPairs = [
['#dev_check_tenkai_01_02', '#dev_check_time_01_02'],
['#dev_check_tenkai_01_03', '#dev_check_time_01_03']
];
function syncCheckboxPair(sourceSelector, targetSelector) {
const $source = $(sourceSelector);
const $target = $(targetSelector);
if (!$source.length || !$target.length) {
return;
}
$target.prop('checked', $source.prop('checked'));
}
window.syncAiTenkaiCheckboxesFromVisibleTab = function() {
const isTenkaiVisible = $('.AiTenkaiArea01').is(':visible');
syncedCheckboxPairs.forEach(function(pair) {
const sourceSelector = isTenkaiVisible ? pair[0] : pair[1];
const targetSelector = isTenkaiVisible ? pair[1] : pair[0];
syncCheckboxPair(sourceSelector, targetSelector);
});
};
window.syncAiTenkaiCheckboxesByInput = function($input) {
syncedCheckboxPairs.forEach(function(pair) {
if ($input.is(pair[0])) {
syncCheckboxPair(pair[0], pair[1]);
} else if ($input.is(pair[1])) {
syncCheckboxPair(pair[1], pair[0]);
}
});
};
// タブ切替
$('.TabMenu01 ul li').on('click', function () {
window.syncAiTenkaiCheckboxesFromVisibleTab();
$("[class^='AiTenkaiArea']").not($($(this).data('tab'))).hide();
$('.' + $(this).data('tab')).show();
$(this).addClass('Active').siblings().removeClass('Active');
});
});

