function setAchievementsView(isExpanded, withAnimation) {
$toggle.attr('aria-expanded', String(isExpanded));
$summary.toggleClass(tickerTapClass, isExpanded);
if (withAnimation) {
if (isExpanded) {
$ticker.stop(true, true).slideUp('fast');
$detail.stop(true, true).slideDown('fast');
} else {
$detail.stop(true, true).slideUp('fast');
$ticker.stop(true, true).slideDown('fast');
}
return;
}
$ticker.toggle(!isExpanded);
$detail.toggle(isExpanded);
}
function toggleDetail() {
var nextExpanded = $(this).attr('aria-expanded') !== 'true';
setAchievementsView(nextExpanded, true);
}
$toggle.off('click.aiTenkai').on('click.aiTenkai', toggleDetail);
$toggle.off('keydown.aiTenkai').on('keydown.aiTenkai', function (e) {
