});
$('.Ai_TenkaiAchievements dl').each(function (index) {
var $dl = $(this);
var $summary = $dl.children('.Ai_TenkaiAchievements_Item_Summary').first();
var $detail = $dl.children('.Ai_TenkaiAchievements_Item_Detail').first();
var $toggle = $summary.find('.Ai_TenkaiAchievements_Toggle').first();
var $ticker = $summary.find('.js-ai-tenkai-ticker').first();
var $tickerContent = $ticker.find('.Ai_TenkaiAchievements_TickerContent').first();
if (!$summary.length || !$detail.length || !$toggle.length || !$ticker.length || !$tickerContent.length) {
return;
}
var detailId = $detail.attr('id') || 'ai-tenkai-achievements-detail-' + index;
var tickerTapClass = 'is-open-ticker-tapped';
$detail.attr('id', detailId);
$toggle.attr('aria-controls', detailId).attr('aria-expanded', 'false');
function setAchievementsView(isExpanded, withAnimation) {
$toggle.attr('aria-expanded', String(isExpanded));
$summary.toggleClass(tickerTapClass, isExpanded);
if (withAnimation) {
if (isExpanded) {
$ticker.stop(true, true).slideUp('fast');
$detail.stop(true, true).slideDown('fast');
} else {
$detail.stop(true, true).slideUp('fast');
$ticker.stop(true, true).slideDown('fast');
}
return;
}
$ticker.toggle(!isExpanded);
$detail.toggle(isExpanded);
}
function toggleDetail() {
var nextExpanded = $(this).attr('aria-expanded') !== 'true';
setAchievementsView(nextExpanded, true);
}
$toggle.off('click.aiTenkai').on('click.aiTenkai', toggleDetail);
$toggle.off('keydown.aiTenkai').on('keydown.aiTenkai', function (e) {
if (e.key === 'Enter' || e.key === ' ') {
e.preventDefault();
toggleDetail.call(this);
}
});
$ticker.off('click.aiTenkaiOpen').on('click.aiTenkaiOpen', function () {
if ($toggle.attr('aria-expanded') !== 'true') {
setAchievementsView(true, true);
}
});
$detail.off('click.aiTenkaiClose').on('click.aiTenkaiClose', function () {
if ($toggle.attr('aria-expanded') === 'true') {
setAchievementsView(false, true);
}
});
setAchievementsView(false, false);
if ($ticker.data('tickerInitialized')) {
return;
}
$ticker.data('tickerInitialized', true);
var $clone = $tickerContent.clone().attr('aria-hidden', 'true');
$ticker.append($clone);
var scrollPos = 0;
var speed = 0.84;
var isPaused = false;
var canHoverPause = window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches;
if (canHoverPause) {
$ticker.on('mouseenter.aiTenkaiTicker', function () {
isPaused = true;
}).on('mouseleave.aiTenkaiTicker', function () {
isPaused = false;
});
}
function tick() {
if (!$ticker.is(':visible')) {
window.requestAnimationFrame(tick);
return;
}
if (!isPaused) {
scrollPos += speed;
if (scrollPos >= $tickerContent.outerWidth(true)) {
scrollPos = 0;
}
$ticker.scrollLeft(scrollPos);
}
window.requestAnimationFrame(tick);
}
window.requestAnimationFrame(tick);
});
